//! `varun completions <SHELL>` and the hidden `varun man`, both generated by clap.

use clap::CommandFactory;

use crate::cli::{Cli, Shell};
use crate::error::{CliError, Result};

pub fn completions(shell: Shell) -> Result<String> {
    let shell = match shell {
        Shell::Bash => clap_complete::Shell::Bash,
        Shell::Zsh => clap_complete::Shell::Zsh,
        Shell::Fish => clap_complete::Shell::Fish,
    };
    let mut buffer = Vec::new();
    clap_complete::generate(shell, &mut Cli::command(), "varun", &mut buffer);
    String::from_utf8(buffer).map_err(|e| CliError::Other(e.to_string()))
}

pub fn man() -> Result<String> {
    let mut buffer = Vec::new();
    clap_mangen::Man::new(Cli::command()).render(&mut buffer).map_err(|e| CliError::Other(e.to_string()))?;
    String::from_utf8(buffer).map_err(|e| CliError::Other(e.to_string()))
}
